+    fn try_from(level: u32) -> std::result::Result<Self, Self::Error> {
+        match level {
+            0 => Ok(Self::PauseOnly),
+            1 => Ok(Self::OffloadWeights),
+            2 => Ok(Self::DiscardAll),
+            other => Err(format!(
+                "invalid sleep level `{other}`; expected one of: 0, 1, 2"
+            )),
